static int hxv(int c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool hexbytes(const char*h,DarcBuf*b){darc_buf_init(b);size_t n=strlen(h);if(n%2)return false;for(size_t i=0;i<n;i+=2){int a=hxv((unsigned char)h[i]),z=hxv((unsigned char)h[i+1]);if(a<0||z<0){darc_buf_free(b);return false;}if(darc_buf_u8(b,(uint8_t)((a<<4)|z))){darc_buf_free(b);return false;}}return true;}
static bool cidhex(const DarcCid*c,const char*h){char x[65];darc_cid_hex(c,x);return !strcmp(x,h);}
static TestProc fi(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc fsnap(const char*r,const char*s,const char*t){const char*a[]={"./darc","--repo",r,"snapshot","create",s,"--timestamp",t,NULL};return test_exec(a,NULL);}
static bool raw_frame_write(const char*r,const DarcCid*cid,uint8_t type,uint8_t codec,uint64_t ul,const uint8_t*p,size_t n){char*hpath=darc_object_path(r,cid);if(!hpath)return false;char*dir=darc_dirname_dup(hpath);bool ok=dir&&!darc_mkdir_p(dir,0755);free(dir);DarcBuf b;darc_buf_init(&b);if(ok)ok=!darc_buf_put(&b,"DARCOBJ1",8)&&!darc_buf_u8(&b,type)&&!darc_buf_u8(&b,codec)&&!darc_buf_u16(&b,0)&&!darc_buf_u64(&b,ul)&&!darc_buf_u64(&b,(uint64_t)n)&&!darc_buf_u32(&b,darc_crc32c(b.data+8,20))&&!darc_buf_put(&b,p,n)&&!darc_buf_u32(&b,darc_crc32c(p,n))&&!test_write(hpath,b.data,b.len,0644);darc_buf_free(&b);free(hpath);return ok;}
static bool object_paths_lower(const char*r){char*root=test_path(r,"objects/sha256");DIR*d=root?opendir(root):NULL;if(!d){free(root);return false;}bool ok=true;struct dirent*e;while((e=readdir(d))&&ok){if(e->d_name[0]=='.')continue;if(strlen(e->d_name)!=2){ok=false;break;}for(int i=0;i<2;i++)if(!((e->d_name[i]>='0'&&e->d_name[i]<='9')||(e->d_name[i]>='a'&&e->d_name[i]<='f')))ok=false;char*sub=test_path(root,e->d_name);DIR*sd=sub?opendir(sub):NULL;if(!sd){free(sub);ok=false;break;}struct dirent*z;while((z=readdir(sd))&&ok){if(z->d_name[0]=='.')continue;if(strlen(z->d_name)!=62){ok=false;break;}for(int i=0;i<62;i++)if(!((z->d_name[i]>='0'&&z->d_name[i]<='9')||(z->d_name[i]>='a'&&z->d_name[i]<='f')))ok=false;}closedir(sd);free(sub);}closedir(d);free(root);return ok;}

void test_format(void){
 const char *filehex="0100030000000000000001000000000000001c896a269e4f99f1a3f1b31f117149b258adfed66201de287e49f03c20488ffe0300000000000000ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";
 const char *treehex="010001000000000000000500000000000000612e74787401a401000000000000000000009d5b5efc84207796ade4ff10b166c53146d750c205ee4e68cdb1254d389120050000000000000000";
 const char *snaphex="";
 const char *framehex="444152434f424a31010000000300000000000000030000000000000019463a43616263b73f4b36";
 DarcBuf exp={0},got={0};DarcCid cid;
 /* FMT-001 exact framed raw CHUNK. */
 {char*d=test_case_dir("fmt001"),*r=test_path(d,"repo");TestProc x=fi(r);test_proc_free(&x);DarcConfig c;darc_config_defaults(&c);c.compression_enabled=false;bool nn=false;uint64_t sb=0;int rc=darc_object_store(r,OBJ_CHUNK,(const uint8_t*)"abc",3,&c,&cid,&sb,&nn);darc_config_free(&c);char*p=darc_object_path(r,&cid);bool ok=!rc&&nn&&p&&!test_read(p,&got)&&hexbytes(framehex,&exp)&&got.len==exp.len&&!memcmp(got.data,exp.data,exp.len)&&cidhex(&cid,"1c896a269e4f99f1a3f1b31f117149b258adfed66201de287e49f03c20488ffe");test_check("FMT-001",ok,"raw CHUNK framing bytes/header CRC/payload CRC/CID match normative golden");darc_buf_free(&got);darc_buf_free(&exp);free(p);free(r);free(d);}
 /* FMT-002 exact FILE payload. */
 {DarcFileObj f;memset(&f,0,sizeof f);f.logical_size=3;f.chunk_n=1;f.chunks=calloc(1,sizeof* f.chunks);darc_hex_cid("1c896a269e4f99f1a3f1b31f117149b258adfed66201de287e49f03c20488ffe",&f.chunks[0].cid);f.chunks[0].len=3;darc_sha256("abc",3,f.digest);bool ok=!darc_file_serialize(&f,&got)&&hexbytes(filehex,&exp);darc_object_cid(OBJ_FILE,got.data,got.len,&cid);ok=ok&&got.len==exp.len&&!memcmp(got.data,exp.data,exp.len)&&cidhex(&cid,"9d5b5efc84207796ade4ff10b166c53146d750c205ee4e68cdb1254d38912005");test_check("FMT-002",ok,"FILE canonical payload and CID match normative golden");darc_buf_free(&got);darc_buf_free(&exp);darc_file_free(&f);}
 /* FMT-003 sorting plus exact source TREE golden. */
 {DarcTreeEnt e;memset(&e,0,sizeof e);e.name=(uint8_t*)"a.txt";e.name_len=5;e.type=1;e.mode=0644;e.mtime_ns=0;darc_hex_cid("9d5b5efc84207796ade4ff10b166c53146d750c205ee4e68cdb1254d38912005",&e.cid);DarcTreeObj t={&e,1};bool ok=!darc_tree_serialize(&t,&got)&&hexbytes(treehex,&exp);darc_object_cid(OBJ_TREE,got.data,got.len,&cid);ok=ok&&got.len==exp.len&&!memcmp(got.data,exp.data,exp.len)&&cidhex(&cid,"93836f6341ca74b1ba0ae0f930def72fe381ebcd7890a717a1327c7748f11522");darc_buf_free(&got);darc_buf_free(&exp);DarcTreeEnt es[2];memset(es,0,sizeof es);es[0].name=(uint8_t*)"z";es[0].name_len=1;es[0].type=2;es[0].mode=0755;es[1].name=(uint8_t*)"a";es[1].name_len=1;es[1].type=2;es[1].mode=0755;DarcTreeObj u={es,2};DarcTreeObj parsed={0};ok=ok&&!darc_tree_serialize(&u,&got)&&!darc_tree_parse(got.data,got.len,&parsed)&&parsed.n==2&&parsed.e[0].name_len==1&&parsed.e[0].name[0]=='a'&&parsed.e[1].name[0]=='z';test_check("FMT-003",ok,"TREE exact golden matches and unsorted input is canonical bytewise name-sorted");darc_tree_free(&parsed);darc_buf_free(&got);}
 /* FMT-004 exact SNAPSHOT golden. */
 {DarcSnapshotObj s;memset(&s,0,sizeof s);s.created_ns=0;darc_hex_cid("0a6bcdce3f96743ae34001eaa6180a3bfea43e3dd168bb75e3c14023bd9adda1",&s.root);s.root_mode=0755;s.root_mtime_ns=0;s.root_n=1;s.roots=calloc(1,sizeof(char*));s.roots[0]=strdup("root");darc_hex_cid("971dd56be6ab862b4739c195c162413d4410351a05b0a70c9efa56ac20037d2f",&s.profile_hash);s.logical_bytes=3;s.files=1;s.dirs=1;s.unique_chunks=1;s.new_chunks=1;s.new_stored_bytes=3;bool ok=!darc_snapshot_serialize(&s,&got)&&hexbytes(snaphex,&exp);darc_object_cid(OBJ_SNAPSHOT,got.data,got.len,&cid);ok=ok&&got.len==exp.len&&!memcmp(got.data,exp.data,exp.len)&&cidhex(&cid,"5000f7d2a8ba493b4431b60460248f2b30813de7505da9b1d8216ef2c98e339c");test_check("FMT-004",ok,"SNAPSHOT canonical payload and CID match normative golden");darc_buf_free(&got);darc_buf_free(&exp);darc_snapshot_free(&s);}
 /* FMT-005 poison struct storage; output must still equal canonical golden. */
 {DarcFileObj f;memset(&f,0xA5,sizeof f);DarcChunkRef cr;memset(&cr,0x5A,sizeof cr);f.logical_size=3;f.chunks=&cr;f.chunk_n=1;darc_hex_cid("1c896a269e4f99f1a3f1b31f117149b258adfed66201de287e49f03c20488ffe",&cr.cid);cr.len=3;darc_sha256("abc",3,f.digest);bool ok=!darc_file_serialize(&f,&got)&&hexbytes(filehex,&exp)&&got.len==exp.len&&!memcmp(got.data,exp.data,exp.len);test_check("FMT-005",ok,"canonical serializer ignores native struct padding/poison bytes");darc_buf_free(&got);darc_buf_free(&exp);}
 /* FMT-006 unsupported semantic version reaches stable exit 10. */
 {char*d=test_case_dir("fmt006"),*r=test_path(d,"repo");TestProc x=fi(r);test_proc_free(&x);uint8_t p2[2]={2,0};DarcConfig c;darc_config_defaults(&c);bool nn;uint64_t sb;int sr=darc_object_store(r,OBJ_FILE,p2,sizeof p2,&c,&cid,&sb,&nn);darc_config_free(&c);darc_index_rebuild(r);const char*a[]={"./darc","--repo",r,"verify","--level","full",NULL};x=test_exec(a,NULL);test_check("FMT-006",sr==0&&x.code==10&&test_contains(x.err,"E_UNSUPPORTED_OBJECT"),"unknown semantic object version rejected as unsupported exit 10");test_proc_free(&x);free(r);free(d);}
 /* FMT-007 unknown codec. */
 {char*d=test_case_dir("fmt007"),*r=test_path(d,"repo");TestProc x=fi(r);test_proc_free(&x);uint8_t p[]={1,2,3};darc_object_cid(OBJ_CHUNK,p,sizeof p,&cid);bool ok=raw_frame_write(r,&cid,OBJ_CHUNK,2,sizeof p,p,sizeof p);darc_index_rebuild(r);const char*a[]={"./darc","--repo",r,"verify","--level","full",NULL};x=test_exec(a,NULL);test_check("FMT-007",ok&&(x.code==6||x.code==10),"unknown codec id is rejected rather than guessed");test_proc_free(&x);free(r);free(d);}
 /* FMT-008 lowercase 2+62 path. */
 {char*d=test_case_dir("fmt008"),*r=test_path(d,"repo"),*s=test_path(d,"src"),*p=test_path(s,"a");test_mkdir(s);test_write(p,"abc",3,0644);TestProc x=fi(r);test_proc_free(&x);x=fsnap(r,s,"7");test_proc_free(&x);test_check("FMT-008",object_paths_lower(r),"all canonical object filenames use lower-case 2+62 CID hex layout");free(p);free(s);free(r);free(d);}
 /* FMT-009 fixed timestamp across equivalent repos. */
 {char*d=test_case_dir("fmt009"),*r1=test_path(d,"r1"),*r2=test_path(d,"r2"),*s=test_path(d,"src"),*p=test_path(s,"a");test_mkdir(s);test_write(p,"same",4,0644);TestProc x=fi(r1);test_proc_free(&x);x=fi(r2);test_proc_free(&x);x=fsnap(r1,s,"999");test_proc_free(&x);x=fsnap(r2,s,"999");test_proc_free(&x);char h1[65],h2[65];test_head(r1,h1);test_head(r2,h2);DarcCid c1,c2;darc_hex_cid(h1,&c1);darc_hex_cid(h2,&c2);DarcBuf b1={0},b2={0};char*o1=darc_object_path(r1,&c1),*o2=darc_object_path(r2,&c2);bool ok=!strcmp(h1,h2)&&o1&&o2&&!test_read(o1,&b1)&&!test_read(o2,&b2)&&b1.len==b2.len&&!memcmp(b1.data,b2.data,b1.len);test_check("FMT-009",ok,"equivalent trees/config/fixed timestamp yield identical snapshot CID/object bytes");darc_buf_free(&b1);darc_buf_free(&b2);free(o2);free(o1);free(p);free(s);free(r2);free(r1);free(d);}
 /* FMT-010 directory creation order invariance. */
 {char*d=test_case_dir("fmt010"),*x1=test_path(d,"x1"),*x2=test_path(d,"x2"),*s1=test_path(x1,"src"),*s2=test_path(x2,"src"),*r1=test_path(x1,"repo"),*r2=test_path(x2,"repo");test_mkdir(s1);test_mkdir(s2);char*p=test_path(s1,"a"),*q=test_path(s1,"b");test_write(p,"A",1,0644);test_write(q,"B",1,0644);free(p);free(q);q=test_path(s2,"b");p=test_path(s2,"a");test_write(q,"B",1,0644);test_write(p,"A",1,0644);free(q);free(p);struct timespec mt[2]={{.tv_sec=1,.tv_nsec=0},{.tv_sec=1,.tv_nsec=0}};p=test_path(s1,"a");q=test_path(s1,"b");utimensat(AT_FDCWD,p,mt,0);utimensat(AT_FDCWD,q,mt,0);free(p);free(q);p=test_path(s2,"a");q=test_path(s2,"b");utimensat(AT_FDCWD,p,mt,0);utimensat(AT_FDCWD,q,mt,0);free(p);free(q);utimensat(AT_FDCWD,s1,mt,0);utimensat(AT_FDCWD,s2,mt,0);TestProc z=fi(r1);test_proc_free(&z);z=fi(r2);test_proc_free(&z);z=fsnap(r1,s1,"1234");test_proc_free(&z);z=fsnap(r2,s2,"1234");test_proc_free(&z);DarcCid i1,i2;DarcSnapshotObj a={0},b={0};bool ok=!darc_resolve_snapshot(r1,"HEAD",&i1,&a)&&!darc_resolve_snapshot(r2,"HEAD",&i2,&b)&&darc_cid_eq(&a.root,&b.root);test_check("FMT-010",ok,"reverse filesystem creation order yields same root TREE CID");darc_snapshot_free(&a);darc_snapshot_free(&b);free(r2);free(r1);free(s2);free(s1);free(x2);free(x1);free(d);}
}
